import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<String> backends = Arrays.asList("B1", "B2", "B3");

        System.out.println("Round robin assignments:");
        for (int i = 0; i < 6; i++) {
            System.out.println("  Request " + (i + 1) + " -> " + roundRobin(backends, i));
        }

        Map<String, Integer> activeConnections = new LinkedHashMap<>();
        activeConnections.put("B1", 0);
        activeConnections.put("B2", 2);
        activeConnections.put("B3", 1);

        System.out.println("Least connections assignments:");
        for (int i = 0; i < 3; i++) {
            String chosen = leastConnections(backends, activeConnections);
            activeConnections.put(chosen, activeConnections.get(chosen) + 1);
            System.out.println("  Request " + (i + 1) + " -> " + chosen + " (now at " + activeConnections.get(chosen) + " active connections)");
        }
    }

    // Round robin simply cycles through backends in a fixed sequence.
    static String roundRobin(List<String> backends, int requestIndex) {
        return backends.get(requestIndex % backends.size());
    }

    // Least connections always picks the backend with the fewest active
    // connections right now, ties broken by earliest position in the list.
    static String leastConnections(List<String> backends, Map<String, Integer> activeConnections) {
        String best = null;
        int bestCount = Integer.MAX_VALUE;
        for (String backend : backends) {
            int count = activeConnections.get(backend);
            if (count < bestCount) {
                bestCount = count;
                best = backend;
            }
        }
        return best;
    }
}

