def round_robin(backends, request_index):
    # Round robin simply cycles through backends in a fixed sequence.
    return backends[request_index % len(backends)]


def least_connections(backends, active_connections):
    # Least connections always picks the backend with the fewest active
    # connections right now, ties broken by earliest position in the list.
    best = None
    best_count = float("inf")
    for backend in backends:
        count = active_connections[backend]
        if count < best_count:
            best_count = count
            best = backend
    return best


def main():
    backends = ["B1", "B2", "B3"]

    print("Round robin assignments:")
    for i in range(6):
        print(f"  Request {i + 1} -> {round_robin(backends, i)}")

    active_connections = {"B1": 0, "B2": 2, "B3": 1}

    print("Least connections assignments:")
    for i in range(3):
        chosen = least_connections(backends, active_connections)
        active_connections[chosen] += 1
        print(f"  Request {i + 1} -> {chosen} (now at {active_connections[chosen]} active connections)")


if __name__ == "__main__":
    main()

