#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <climits>
using namespace std;

// Round robin simply cycles through backends in a fixed sequence.
string roundRobin(const vector<string>& backends, int requestIndex) {
    return backends[requestIndex % backends.size()];
}

// Least connections always picks the backend with the fewest active
// connections right now, ties broken by earliest position in the list.
string leastConnections(const vector<string>& backends, map<string, int>& activeConnections) {
    string best = "";
    int bestCount = INT_MAX;
    for (const auto& backend : backends) {
        int count = activeConnections[backend];
        if (count < bestCount) {
            bestCount = count;
            best = backend;
        }
    }
    return best;
}

int main() {
    vector<string> backends = {"B1", "B2", "B3"};

    cout << "Round robin assignments:" << endl;
    for (int i = 0; i < 6; i++) {
        cout << "  Request " << (i + 1) << " -> " << roundRobin(backends, i) << endl;
    }

    map<string, int> activeConnections = {{"B1", 0}, {"B2", 2}, {"B3", 1}};

    cout << "Least connections assignments:" << endl;
    for (int i = 0; i < 3; i++) {
        string chosen = leastConnections(backends, activeConnections);
        activeConnections[chosen]++;
        cout << "  Request " << (i + 1) << " -> " << chosen << " (now at " << activeConnections[chosen] << " active connections)" << endl;
    }

    return 0;
}
